#include <Arduino.h>
const int buttonPin = 4;
QueueHandle_t events = nullptr;
portMUX_TYPE dropMux = portMUX_INITIALIZER_UNLOCKED;
uint32_t droppedEvents = 0;
void IRAM_ATTR buttonIsr() { const int event = 1; BaseType_t higherPriorityTaskWoken = pdFALSE; if (events == nullptr || xQueueSendFromISR(events, &event, &higherPriorityTaskWoken) != pdPASS) { portENTER_CRITICAL_ISR(&dropMux); ++droppedEvents; portEXIT_CRITICAL_ISR(&dropMux); } if (higherPriorityTaskWoken == pdTRUE) portYIELD_FROM_ISR(); }
void setup() { Serial.begin(115200); events = xQueueCreate(4, sizeof(int)); if (events == nullptr) { Serial.println("event queue creation failed"); return; } pinMode(buttonPin, INPUT_PULLUP); attachInterrupt(digitalPinToInterrupt(buttonPin), buttonIsr, FALLING); }
void loop() { int event; if (events && xQueueReceive(events, &event, pdMS_TO_TICKS(1000)) == pdPASS) { uint32_t dropped; portENTER_CRITICAL(&dropMux); dropped = droppedEvents; portEXIT_CRITICAL(&dropMux); Serial.printf("button event; dropped=%lu\n", static_cast<unsigned long>(dropped)); } else { vTaskDelay(pdMS_TO_TICKS(100)); } }

#include <Arduino.h>
const int buttonPin = 4;
QueueHandle_t events;
void IRAM_ATTR onPress() { int event = 1; BaseType_t wake = pdFALSE; if (events) xQueueSendFromISR(events, &event, &wake); if (wake == pdTRUE) portYIELD_FROM_ISR(); }
void setup() { Serial.begin(115200); events = xQueueCreate(4, sizeof(int)); if (events) { pinMode(buttonPin, INPUT_PULLUP); attachInterrupt(digitalPinToInterrupt(buttonPin), onPress, FALLING); } }
void loop() { int event; if (events && xQueueReceive(events, &event, portMAX_DELAY) == pdPASS) Serial.println("button event"); }
